export type MicrosoftFoundryHostname = `${string}${(typeof validHostnames)[number]}${string}`

// Keep in sync with `VALID_MSFOUNDRY_HOSTNAMES` in packages/copilot_byok/app/models/copilot_byok/custom_key.rb
// in github/github and with `validHosts` in pkg/byok/byokprovider/microsoft_foundry.go in github/copilot-api
const validHostnames = [
  'models.ai.azure.com',
  'inference.ml.azure.com',
  'openai.azure.com',
  'services.ai.azure.com',
  'cognitiveservices.azure.com',
  'ai.openai.azure.us',
] as const

export function isValidMicrosoftFoundryHostname(value: unknown): value is MicrosoftFoundryHostname {
  if (typeof value !== 'string') return false
  try {
    // We want to try and create a url out of the value to validate it
    // eslint-disable-next-line no-restricted-syntax
    const url = new URL(value)
    const hostname = url.hostname.toLowerCase()
    return validHostnames.some(h => hostname === h || hostname.endsWith(`.${h}`))
  } catch {
    return false
  }
}
