import {IS_BROWSER} from '@github-ui/ssr-utils'
import {Portal, registerPortalRoot} from '@primer/react'
import {clsx} from 'clsx'
import {cloneElement, type ReactElement, useSyncExternalStore} from 'react'
import {useLayoutEffect} from '@github-ui/use-layout-effect'

import styles from './PageBanner.module.css'

type BannerElement = ReactElement<{className?: string; onDismiss?: () => void}>

const zone: ReturnType<typeof createStore> = createStore()

export function setBanner(el: BannerElement) {
  zone.set(el)
}

function createStore() {
  let callback: (() => void) | null = null
  let currentBanner: BannerElement | null = null

  function update() {
    callback?.()
  }

  return {
    subscribe: (cb: () => void) => {
      callback = cb
      return () => {
        currentBanner = null
        callback = null
      }
    },
    getSnapshot: (): BannerElement | null => {
      return currentBanner
    },
    dismiss: () => {
      currentBanner = null
      update()
    },
    set: (el: BannerElement) => {
      currentBanner = el
      update()
    },
  }
}

export function PageBannerOutlet() {
  const containerName = useEnsureFlashContainer()

  // At this stage, banners cannot be set on the server, so just return null.
  const el = useSyncExternalStore(zone.subscribe, zone.getSnapshot, () => null)

  if (el == null) return null

  return (
    <Portal containerName={containerName}>
      {cloneElement(el, {className: clsx(styles.PageBanner, el.props.className), onDismiss: zone.dismiss})}
    </Portal>
  )
}

function useEnsureFlashContainer() {
  const containerName = 'flashContainer'

  useLayoutEffect(() => {
    let cleanupNode: HTMLElement | null = null

    if (IS_BROWSER) {
      // If we have a js-flash-container, use that (this is what the app shell provides)
      let flashContainer = document.getElementById('js-flash-container')
      if (!flashContainer) {
        cleanupNode = flashContainer = fallbackFlashContainer()
      }

      registerPortalRoot(flashContainer, containerName)
    }

    return () => {
      cleanupNode?.remove()
    }
  }, [])

  return containerName
}

function fallbackFlashContainer() {
  // Try if the AppHeader exists, the banner should be a sibling of that.
  const appHeader = document.getElementsByClassName('AppHeader')?.[0]

  const container = document.createElement('div')
  container.id = 'js-flash-container'

  if (appHeader) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    appHeader.parentElement!.insertBefore(container, appHeader.nextElementSibling)
    return container
  }

  // Otherwise insert at the top of the body
  return document.body.insertBefore(container, document.body.firstElementChild)
}

try{ PageBannerOutlet.displayName ||= 'PageBannerOutlet' } catch {}