import {Banner, Checkbox, CheckboxGroup, FormControl, Stack, TextInput} from '@primer/react'
import {useId} from 'react'

import type {ValidationKind} from '../helpers/validation'
import type {CustomModel} from '../types'
import {FormValidationNode} from './FormValidationNode'

interface ModelConfigurationFieldsProps {
  className?: string | undefined
  model: CustomModel
  disabled?: boolean
  validation?: Record<string, ValidationKind>
}

export function ModelConfigurationFields({className, disabled, model, validation}: ModelConfigurationFieldsProps) {
  const baseId = useId()
  const displayNameValidationId = `name-${baseId}`
  const toolCallingValidationId = `tool_calling-${baseId}`
  const visionValidationId = `vision-${baseId}`
  const thinkingValidationId = `thinking-${baseId}`
  const maxInputTokensValidationId = `max_input_tokens-${baseId}`
  const maxOutputTokensValidationId = `max_output_tokens-${baseId}`

  return (
    <Stack.Item grow className={className}>
      {validation?.__general && (
        <Banner
          className="mb-3"
          role="banner"
          title="Error"
          variant="critical"
          hideTitle
          description={validation.__general.error}
        />
      )}
      <FormControl disabled>
        <FormControl.Label>Model name</FormControl.Label>
        <TextInput name="slug" defaultValue={model.slug} className="width-full" />
      </FormControl>
      <FormControl disabled={disabled} className="mt-3">
        <FormControl.Label>Display name</FormControl.Label>
        <TextInput
          name="name"
          defaultValue={model.name}
          aria-describedby={displayNameValidationId}
          className="width-full"
        />
        <FormValidationNode item={validation?.name} id={displayNameValidationId} />
      </FormControl>
      <CheckboxGroup className="mt-3">
        <CheckboxGroup.Label>Capabilities</CheckboxGroup.Label>
        <FormControl disabled={disabled}>
          <FormControl.Label>Tool calling (required for agent mode)</FormControl.Label>
          <Checkbox
            name="toolCalling"
            defaultValue="1"
            defaultChecked={model.toolCalling}
            aria-describedby={toolCallingValidationId}
          />
          <FormValidationNode item={validation?.toolCalling} id={toolCallingValidationId} />
        </FormControl>
        <FormControl disabled={disabled}>
          <FormControl.Label>Vision</FormControl.Label>
          <Checkbox
            name="vision"
            defaultValue="1"
            defaultChecked={model.vision}
            aria-describedby={visionValidationId}
          />
          <FormValidationNode item={validation?.vision} id={visionValidationId} />
        </FormControl>
        <FormControl disabled={disabled}>
          <FormControl.Label>Thinking</FormControl.Label>
          <Checkbox
            name="thinking"
            defaultValue="1"
            defaultChecked={model.thinking}
            aria-describedby={thinkingValidationId}
          />
          <FormValidationNode item={validation?.thinking} id={thinkingValidationId} />
        </FormControl>
      </CheckboxGroup>
      <FormControl disabled={disabled} className="mt-3">
        <FormControl.Label>Maximum input tokens</FormControl.Label>
        <TextInput
          type="number"
          name="maxInputTokens"
          step="1"
          min="0"
          className="width-full"
          aria-describedby={maxInputTokensValidationId}
          defaultValue={model.maxInputTokens && model.maxInputTokens > 0 ? model.maxInputTokens : ''}
        />
        <FormValidationNode item={validation?.maxInputTokens} id={maxInputTokensValidationId} />
      </FormControl>
      <FormControl disabled={disabled} className="mt-3">
        <FormControl.Label>Maximum output tokens</FormControl.Label>
        <TextInput
          type="number"
          name="maxOutputTokens"
          step="1"
          min="0"
          className="width-full"
          aria-describedby={maxOutputTokensValidationId}
          defaultValue={model.maxOutputTokens && model.maxOutputTokens > 0 ? model.maxOutputTokens : ''}
        />
        <FormValidationNode item={validation?.maxOutputTokens} id={maxOutputTokensValidationId} />
      </FormControl>
    </Stack.Item>
  )
}

try{ ModelConfigurationFields.displayName ||= 'ModelConfigurationFields' } catch {}